import{_ as o,I as r,g as a,j as s}from"./chunks/framework.Ha9mtr6N.js";const h=JSON.parse('{"title":"Быстрый старт","description":"Первые шаги в ОмниКрафт ЕРП. Базовая настройка, перенос остатков и принципы безопасности данных.","frontmatter":{"title":"Быстрый старт","description":"Первые шаги в ОмниКрафт ЕРП. Базовая настройка, перенос остатков и принципы безопасности данных.","order":3},"headers":[],"relativePath":"ru/docs/getting-started.md","filePath":"ru/docs/getting-started.md"}'),e={name:"ru/docs/getting-started.md"};function n(l,t,i,g,d,c){return r(),a("div",null,[...t[0]||(t[0]=[s('<div class="warning custom-block"><p class="custom-block-title">📌 Документация находится в разработке</p><p><strong>Уважаемые пользователи!</strong></p><p>Поскольку ОмниКрафт ЕРП сейчас находится в стадии активной бета-версии, регулярно дорабатывается и расширяется, справочные материалы также обновляются постепенно.</p><p>На данный момент воспринимайте документацию как ориентировочную — она является неполной, может временно не содержать описание некоторых функций или содержать неточности.</p></div><h1 id="быстрыи-старт" tabindex="-1">Быстрый старт <a class="header-anchor" href="#быстрыи-старт" aria-label="Permalink to &quot;Быстрый старт&quot;">​</a></h1><p>Эта страница поможет вам правильно настроить ОмниКрафт ЕРП при первом запуске и безболезненно перенести данные в программу из вашего предыдущего учёта (блокнотов, Excel-таблиц или других программ).</p><hr><h2 id="🌍-язык-и-безопасность-данных" tabindex="-1">🌍 Язык и безопасность данных <a class="header-anchor" href="#🌍-язык-и-безопасность-данных" aria-label="Permalink to &quot;🌍 Язык и безопасность данных&quot;">​</a></h2><p><strong>Локализация:</strong> Программа поддерживает несколько языков и при первом запуске автоматически определяет язык вашей операционной системы. Вы всегда можете изменить его вручную: в верхнем меню выберите <strong>Файл ➔ Настройки программы</strong>, выберите нужный язык и перезапустите приложение.</p><p><strong>Безопасность:</strong> Ваши данные — это ваша собственность. Мы <strong>не собираем, не храним и не обрабатываем ваши личные и персональные данные и данные вашего бизнеса</strong>. Программа не требует регистрации с указанием имени, электронной почты или номера телефона.</p><div class="info custom-block"><p class="custom-block-title">О сохранности информации и резервных копиях</p><p>Мы прикладываем все усилия, чтобы свести риски к минимуму: в программу встроены современные инструменты защиты данных, база использует режим WAL (защита от сбоев питания) и делает автоматические теневые копии.</p><p>Тем не менее, стопроцентная гарантия сохранности информации невозможна — потеря данных может произойти из-за системных ошибок ОС, вредоносного ПО, физического износа жесткого диска или по другим причинам. Забота о сохранности данных остается вашей зоной ответственности.</p><p>Рекомендуем периодически создавать ручные бэкапы: <strong>Файл ➔ Экспорт данных</strong>. Основной бинарный бэкап (<code>.db</code>) сохраняет вашу систему целиком. Однако в качестве дополнительного страховочного варианта желательно выгружать данные и во втором формате — <code>.zip</code> с таблицами CSV. Если бинарный файл базы когда-либо получит микроповреждения из-за дисковых сбоев и не откроется в программе, у вас будет запасной вариант восстановления.</p></div><hr><h2 id="🚚-перенос-данных-из-предыдущего-учета" tabindex="-1">🚚 Перенос данных из предыдущего учёта <a class="header-anchor" href="#🚚-перенос-данных-из-предыдущего-учета" aria-label="Permalink to &quot;🚚 Перенос данных из предыдущего учёта&quot;">​</a></h2><p>Если вы переходите на ОмниКрафт ЕРП из другой системы, вам не нужно вручную вбивать историю всех прошлых продаж за несколько лет. Достаточно перенести текущий «срез» вашего бизнеса за два простых шага.</p><h3 id="шаг-1-внесите-текущее-имущество-и-материалы" tabindex="-1">Шаг 1. Внесите текущее имущество и материалы <a class="header-anchor" href="#шаг-1-внесите-текущее-имущество-и-материалы" aria-label="Permalink to &quot;Шаг 1. Внесите текущее имущество и материалы&quot;">​</a></h3><ol><li>Откройте вкладку <strong>Мастерская</strong> и внесите всё ваше текущее оборудование и инструменты по цене их изначальной покупки.</li><li>Откройте вкладку <strong>Сырьё</strong> и внесите фактические остатки материалов (например, кожу, химию, фурнитуру, если у вас кожевенное производство), которые есть у вас на полках прямо сейчас.</li></ol><p><em>Что произойдет:</em> Программа поставит эти ценности на Баланс мастерской. При этом она автоматически зафиксирует траты на их покупку в журнале ДДС (Движения денежных средств). На этом этапе сальдо ДДС логично уйдет в глубокий минус — система зафиксировала объем ваших исторических инвестиций в бизнес.</p><h3 id="шаг-2-внесите-историческое-сальдо-ддс-и-долги" tabindex="-1">Шаг 2. Внесите историческое сальдо ДДС и долги <a class="header-anchor" href="#шаг-2-внесите-историческое-сальдо-ддс-и-долги" aria-label="Permalink to &quot;Шаг 2. Внесите историческое сальдо ДДС и долги&quot;">​</a></h3><p>Независимо от того, окупился ли ваш бизнес в прошлом или вы всё еще возвращаете стартовые вложения, вам необходимо провести стартовую корректирующую операцию. Это синхронизирует программу с реальностью.</p><p>Перейдите во вкладку <strong>ДДС</strong>, нажмите кнопку корректировки и последовательно заполните данные:</p><ol><li><strong>Подтвердите исторические активы:</strong> Программа выведет список имущества, добавленного вами на вкладке <strong>Мастерская</strong> на первом шаге. Отметьте те позиции, которые были приобретены <em>до</em> перехода в ОмниКрафт ЕРП. Программа прибавит их стоимость обратно при расчетах, чтобы не списать эту трату дважды (поскольку вы уже учли их покупку в своем прошлом учете). <strong>Важно:</strong> на этом шаге убедитесь, что вы отметили абсолютно всё историческое имущество и расходники (за исключением сырья со склада — его отмечать не нужно).</li><li><strong>Внесите долги бизнеса:</strong> Если у мастерской есть непогашенные кредиты, займы или долги перед поставщиками, укажите их. Они автоматически зафиксируются в пассиве вашего Баланса.</li><li><strong>Укажите историческое Сальдо ДДС:</strong> Это итоговый денежный результат за всё время вашего предыдущего учёта. Он считается так: <strong>Все поступления</strong> (выручка от реализации изделий, полученные кредиты и займы, личные инвестиции, прочие поступления) минус <strong>Все расходы</strong> (затраты на сырье и материалы, покупку оборудования, аренду, рекламу, уплату налогов, процентов по кредиту и прочие издержки). <em>Примечание: этот показатель может быть как положительным, так и отрицательным.</em></li></ol><div class="warning custom-block"><p class="custom-block-title">Внимание: корректировка проводится только один раз!</p><p>Эта стартовая корректирующая операция блокируется после первого проведения — запустить её повторно не получится. Поэтому перед тем как нажать кнопку подтверждения, обязательно убедитесь, что на первом шаге вы внесли во вкладку <strong>Мастерская</strong> абсолютно все ваши старые инструменты, станки и расходники.</p><p><strong>Что делать, если вы позже вспомнили про забытый старый актив?</strong> Не переживайте, это легко исправить без поломки учета:</p><ol><li>Добавьте забытый станок или инструмент во вкладку <strong>Мастерская</strong> обычным способом. На балансе появится актив, а в ДДС автоматически запишется расход на сумму его «покупки».</li><li>Чтобы скомпенсировать этот ложный расход (ведь вы физически не тратили деньги сейчас — станок уже был куплен в прошлом), зайдите во вкладку <strong>ДДС</strong> и создайте операцию прихода (например, <strong>Внереализационный доход</strong>) на сумму стоимости этого станка. В комментарии укажите: <em>«Корректировка за забытый исторический актив»</em>.</li></ol></div><p>Всё! Ваша база настроена, математика сведена, а Баланс и ДДС показывают реальную картину.</p><hr><h2 id="🚀-базовые-настроики-ценообразования" tabindex="-1">🚀 Базовые настройки ценообразования <a class="header-anchor" href="#🚀-базовые-настроики-ценообразования" aria-label="Permalink to &quot;🚀 Базовые настройки ценообразования&quot;">​</a></h2><p>Перед тем как перейти к созданию изделий (вкладка Калькулятор), важно задать финансовые правила вашей мастерской. Перейдите во вкладку <strong>Настройки</strong> и установите три главных параметра:</p><h3 id="_1-системная-ставка-мастера-₽-час" tabindex="-1">1. Системная ставка мастера (₽/час) <a class="header-anchor" href="#_1-системная-ставка-мастера-₽-час" aria-label="Permalink to &quot;1. Системная ставка мастера (₽/час)&quot;">​</a></h3><p>Это стоимость одного часа работы мастера.</p><ul><li><strong>Если вы нанимаете помощников:</strong> Укажите здесь их среднюю часовую ставку. Программа будет считать эти деньги прямым расходом и строго включать в себестоимость.</li><li><strong>Если вы работаете на себя (соло-мастер):</strong> Вы можете указать ставку <code>0</code>. В этом случае вам не придется делать лишние проводки по выплате «зарплаты» самому себе. Однако помните: если ваша ставка равна нулю, стоимость вашего труда должна быть заложена в итоговую <em>глобальную наценку</em>.</li></ul><h3 id="_2-глобальная-наценка" tabindex="-1">2. Глобальная наценка (%) <a class="header-anchor" href="#_2-глобальная-наценка" aria-label="Permalink to &quot;2. Глобальная наценка (%)&quot;">​</a></h3><p>Это множитель маржинальности. Программа автоматически применит его к чистой себестоимости изделия (материалы + работа + накладные расходы), чтобы рассчитать для вас <strong>Рекомендуемую розничную цену</strong>.</p><h3 id="_3-накладные-расходы-глобальные-нормативы" tabindex="-1">3. Накладные расходы (Глобальные нормативы) <a class="header-anchor" href="#_3-накладные-расходы-глобальные-нормативы" aria-label="Permalink to &quot;3. Накладные расходы (Глобальные нормативы)&quot;">​</a></h3><p>Накладные расходы — это невидимые затраты, которые несет ваша мастерская: электричество, аренда, расходники. В настройках вы задаете их базовый уровень. Они могут быть двух типов:</p><ul><li><strong>Процентные (%):</strong> Считаются как процент от базовой себестоимости изделия.</li><li><strong>Фиксированные (₽):</strong> Твердая сумма, которая прибавляется к каждому произведенному изделию.</li></ul><p><strong>Индивидуальная настройка в рецептах:</strong> Вам не придется менять глобальные настройки каждый раз, если разные изделия требуют разных затрат. При создании рецепта конкретного изделия в Калькуляторе программа предложит вам умную панель коэффициентов:</p><ul><li>Если на изделие уходит в два раза больше электричества и клея, вы просто ставите в её рецепте коэффициент накладных <code>2.0</code> (программа умножит глобальный норматив на два).</li><li>Если для простого брелока сложное оборудование не используется вовсе, вы ставите коэффициент <code>0</code>, и эти расходы не войдут в его себестоимость.</li></ul><p>После заполнения этих параметров ваша система полностью готова к работе. Вы можете переходить во вкладку <strong>Калькулятор</strong> и создавать свои первые технологические карты изделий.</p>',34)])])}const u=o(e,[["render",n]]);export{h as __pageData,u as default};
